<?php
require_once 'includes/config.php'; require_once 'includes/phase1.php'; require_admin();
$years=$dbh->query('SELECT DISTINCT AcademicYear FROM tblresult WHERE AcademicYear<>\'\' ORDER BY AcademicYear DESC')->fetchAll(PDO::FETCH_COLUMN);
$terms=$dbh->query('SELECT DISTINCT Term FROM tblresult WHERE Term<>\'\' ORDER BY Term')->fetchAll(PDO::FETCH_COLUMN);
$exams=$dbh->query('SELECT DISTINCT ExamType FROM tblresult WHERE ExamType<>\'\' ORDER BY ExamType')->fetchAll(PDO::FETCH_COLUMN);
$year=trim($_GET['academic_year']??'');$term=trim($_GET['term']??'');$exam=trim($_GET['exam_type']??'');$classId=(int)($_GET['class_id']??0);
$classes=$dbh->query('SELECT id,ClassName,Section FROM tblclasses ORDER BY ClassNameNumeric,Section')->fetchAll();
$where=['r.Published=1','r.approval_state=\'approved\''];$p=[];
if($year){$where[]='r.AcademicYear=:y';$p[':y']=$year;}if($term){$where[]='r.Term=:t';$p[':t']=$term;}if($exam){$where[]='r.ExamType=:e';$p[':e']=$exam;}if($classId){$where[]='r.ClassId=:c';$p[':c']=$classId;}
$w=implode(' AND ',$where);
$sql="SELECT c.id,c.ClassName,c.Section,COUNT(DISTINCT r.StudentId) students,COUNT(r.id) marks,ROUND(AVG((r.marks/NULLIF(r.MaxMarks,0))*100),2) avg_pct,ROUND(100*SUM(CASE WHEN (r.marks/NULLIF(r.MaxMarks,0))*100>=40 THEN 1 ELSE 0 END)/NULLIF(COUNT(r.id),0),2) pass_rate,MAX((r.marks/NULLIF(r.MaxMarks,0))*100) highest,MIN((r.marks/NULLIF(r.MaxMarks,0))*100) lowest FROM tblresult r JOIN tblclasses c ON c.id=r.ClassId WHERE $w GROUP BY c.id,c.ClassName,c.Section ORDER BY avg_pct DESC,c.ClassNameNumeric,c.Section";
$q=$dbh->prepare($sql);$q->execute($p);$rows=$q->fetchAll();
$subjectSql="SELECT sub.SubjectName,COUNT(r.id) entries,ROUND(AVG((r.marks/NULLIF(r.MaxMarks,0))*100),2) avg_pct,ROUND(100*SUM(CASE WHEN (r.marks/NULLIF(r.MaxMarks,0))*100>=40 THEN 1 ELSE 0 END)/NULLIF(COUNT(r.id),0),2) pass_rate,MAX((r.marks/NULLIF(r.MaxMarks,0))*100) highest FROM tblresult r JOIN tblsubjects sub ON sub.id=r.SubjectId WHERE $w GROUP BY sub.id,sub.SubjectName ORDER BY avg_pct DESC,sub.SubjectName";
$sq=$dbh->prepare($subjectSql);$sq->execute($p);$subjects=$sq->fetchAll();
$totalStudents=0;$totalMarks=0;$overall=0;$passRate=0;if($rows){$totalStudents=array_sum(array_column($rows,'students'));$totalMarks=array_sum(array_column($rows,'marks'));$overall=round(array_sum(array_map(fn($r)=>$r['avg_pct']*$r['marks'],$rows))/max(1,$totalMarks),2);$passRate=round(array_sum(array_map(fn($r)=>$r['pass_rate']*$r['marks'],$rows))/max(1,$totalMarks),2);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Class Performance Analytics | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><div class="main-page"><div class="container-fluid"><div class="row page-title-div"><div class="col-sm-8"><h2 class="title">Class Performance Analytics</h2><p class="text-muted">Official approved and published results only.</p></div></div><form class="panel panel-default panel-body" method="get"><div class="row"><div class="col-md-3"><label>Academic Year</label><select name="academic_year" class="form-control"><option value="">All Years</option><?php foreach($years as $v):?><option value="<?php echo e($v);?>" <?php echo $year===$v?'selected':'';?>><?php echo e($v);?></option><?php endforeach;?></select></div><div class="col-md-2"><label>Term</label><select name="term" class="form-control"><option value="">All Terms</option><?php foreach($terms as $v):?><option value="<?php echo e($v);?>" <?php echo $term===$v?'selected':'';?>><?php echo e($v);?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Examination</label><select name="exam_type" class="form-control"><option value="">All Examinations</option><?php foreach($exams as $v):?><option value="<?php echo e($v);?>" <?php echo $exam===$v?'selected':'';?>><?php echo e($v);?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Class</label><select name="class_id" class="form-control"><option value="0">All Classes</option><?php foreach($classes as $c):?><option value="<?php echo $c['id'];?>" <?php echo $classId==(int)$c['id']?'selected':'';?>><?php echo e($c['ClassName'].' '.$c['Section']);?></option><?php endforeach;?></select></div><div class="col-md-1"><label>&nbsp;</label><button class="btn btn-primary btn-block">Go</button></div></div></form><div class="row"><div class="col-sm-3"><div class="dashboard-stat bg-primary"><span class="number"><?php echo (int)$totalStudents;?></span><span class="name">Students</span></div></div><div class="col-sm-3"><div class="dashboard-stat bg-success"><span class="number"><?php echo e($overall);?>%</span><span class="name">Overall Average</span></div></div><div class="col-sm-3"><div class="dashboard-stat bg-warning"><span class="number"><?php echo e($passRate);?>%</span><span class="name">Pass Rate</span></div></div><div class="col-sm-3"><div class="dashboard-stat bg-danger"><span class="number"><?php echo count($rows);?></span><span class="name">Classes</span></div></div></div><div class="panel m-t-20"><div class="panel-heading"><h4>Class Performance</h4></div><div class="panel-body"><div class="table-responsive"><table class="table table-bordered table-striped"><thead><tr><th>Class</th><th>Students</th><th>Marks</th><th>Average %</th><th>Pass Rate</th><th>Highest %</th><th>Lowest %</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo e($r['ClassName'].' '.$r['Section']);?></td><td><?php echo (int)$r['students'];?></td><td><?php echo (int)$r['marks'];?></td><td><strong><?php echo e($r['avg_pct']);?>%</strong></td><td><?php echo e($r['pass_rate']);?>%</td><td><?php echo e(number_format((float)$r['highest'],2));?>%</td><td><?php echo e(number_format((float)$r['lowest'],2));?>%</td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="text-center">No published approved results match the selected filters.</td></tr><?php endif;?></tbody></table></div></div></div><div class="panel"><div class="panel-heading"><h4>Subject Performance</h4></div><div class="panel-body"><div class="table-responsive"><table class="table table-bordered"><thead><tr><th>Subject</th><th>Entries</th><th>Average %</th><th>Pass Rate</th><th>Highest %</th></tr></thead><tbody><?php foreach($subjects as $r):?><tr><td><?php echo e($r['SubjectName']);?></td><td><?php echo (int)$r['entries'];?></td><td><?php echo e($r['avg_pct']);?>%</td><td><?php echo e($r['pass_rate']);?>%</td><td><?php echo e(number_format((float)$r['highest'],2));?>%</td></tr><?php endforeach;?><?php if(!$subjects):?><tr><td colspan="5" class="text-center">No subject data available.</td></tr><?php endif;?></tbody></table></div></div></div></div></div></div></div></div><script src="js/jquery/jquery-2.2.4.min.js"></script><script src="js/bootstrap/bootstrap.min.js"></script></body></html>
